function bv_nl_pattern_render( string $name ): string {
	$file = get_theme_file_path( 'patterns/' . $name . '.php' );
	if ( ! is_readable( $file ) ) return '';
	ob_start();
	include $file;
	return strtr( (string) ob_get_clean(), bv_nl_pattern_pairs() );
}

add_action( 'init', static function () {
	$uri = (string) ( $_SERVER['REQUEST_URI'] ?? '' );
	if ( ! is_admin() && 'nl' !== bv_lang() && ! str_contains( $uri, '/wp-json/' ) && ! str_contains( $uri, 'rest_route=' ) ) return;
	foreach ( [ 'hero', 'services-grid', 'growth-guide-cta', 'about', 'testimonials', 'blog-grid', 'contact', 'about-story', 'about-founder', 'core-values', 'approach-steps', 'why-choose-checklist', 'cta-band', 'services-detail', 'additional-services', 'process-steps', 'tools-cards', 'unify-hero', 'unify-friction-to-flow', 'unify-market-clarity', 'unify-phases', 'unify-modules', 'unify-stats', 'newsletter-cta', 'newsletter-inline' ] as $name ) {
		register_block_pattern( 'booming-venture/' . $name . '-nl', [
			'title'    => ucfirst( str_replace( '-', ' ', $name ) ) . ' (NL)',
			'content'  => bv_nl_pattern_render( $name ),
			'inserter' => false,
		] );
	}
}, 9 );
